import { useState } from "react";

export function TestimonialCarousel({
  activeSlide = "{{activeSlide}}",
  accent = "{{accent}}",
  showArrows = {{showArrows}},
}) {
  const slides = [
    { quote: "Cut our reporting time in half.", cite: "Priya, Northwind" },
    { quote: "Support that actually responds fast.", cite: "Omar, Cobalt" },
    { quote: "Rolled out to 40 people in a day.", cite: "Lena, Fenwick" },
  ];
  const [index, setIndex] = useState(Number(activeSlide) - 1);
  const move = (delta) => setIndex((i) => (i + delta + slides.length) % slides.length);
  return (
    <div style={{ font: "16px/1.5 system-ui, sans-serif", color: "#241430", maxWidth: 360, textAlign: "center",
      padding: 24, position: "relative" }}>
      {showArrows && (
        <button type="button" onClick={() => move(-1)} aria-label="Previous testimonial" style={{ position: "absolute",
          top: "50%", left: 0, transform: "translateY(-50%)", background: "none", border: "none", fontSize: 26,
          color: accent, cursor: "pointer", padding: "4px 8px" }}>&#8249;</button>
      )}
      <blockquote style={{ margin: "0 0 16px", fontSize: 17, fontWeight: 500 }}>
        &ldquo;{slides[index].quote}&rdquo;
        <cite style={{ display: "block", marginTop: 10, fontSize: 13, fontStyle: "normal", color: "#241430aa" }}>&mdash; {slides[index].cite}</cite>
      </blockquote>
      {showArrows && (
        <button type="button" onClick={() => move(1)} aria-label="Next testimonial" style={{ position: "absolute",
          top: "50%", right: 0, transform: "translateY(-50%)", background: "none", border: "none", fontSize: 26,
          color: accent, cursor: "pointer", padding: "4px 8px" }}>&#8250;</button>
      )}
      <div role="tablist" aria-label="Testimonials" style={{ display: "flex", gap: 8, justifyContent: "center" }}>
        {slides.map((_, i) => (
          <span key={i} style={{ width: 8, height: 8, borderRadius: "50%", background: i === index ? accent : "#24143025" }} />
        ))}
      </div>
    </div>
  );
}
